<?php require '../config.php'; if(!is_logged()) header('Location: /lftms_full/login.php'); $u=current_user(); if($u['role']!='admin'){ echo 'Access denied'; exit; }
if($_SERVER['REQUEST_METHOD']=='POST'){ $pdo->prepare('INSERT INTO species(name,min_do,max_do,min_temp,max_temp,min_ph,max_ph) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['name'],floatval($_POST['min_do']),floatval($_POST['max_do']),floatval($_POST['min_t']),floatval($_POST['max_t']),floatval($_POST['min_ph']),floatval($_POST['max_ph'])]); header('Location: species.php'); }
$rows=$pdo->query('SELECT * FROM species')->fetchAll(); include '../inc/header.php'; ?>
<h3>Species</h3>
<form method="post" class="row g-2"><div class="col-md-3"><input name="name" class="form-control" placeholder="Name" required></div><div class="col-md-1"><input name="min_do" class="form-control" placeholder="min DO"></div><div class="col-md-1"><input name="max_do" class="form-control" placeholder="max DO"></div><div class="col-md-1"><input name="min_t" class="form-control" placeholder="min T"></div><div class="col-md-1"><input name="max_t" class="form-control" placeholder="max T"></div><div class="col-md-1"><input name="min_ph" class="form-control" placeholder="min pH"></div><div class="col-md-1"><input name="max_ph" class="form-control" placeholder="max pH"></div><div class="col-md-2"><button class="btn btn-success">Add Species</button></div></form>
<table class="table mt-3"><tr><th>ID</th><th>Name</th><th>DO</th><th>Temp</th><th>pH</th></tr><?php foreach($rows as $r): ?><tr><td><?php echo $r['id'];?></td><td><?php echo esc($r['name']);?></td><td><?php echo $r['min_do'].' - '.$r['max_do'];?></td><td><?php echo $r['min_temp'].' - '.$r['max_temp'];?></td><td><?php echo $r['min_ph'].' - '.$r['max_ph'];?></td></tr><?php endforeach; ?></table>
<?php include '../inc/footer.php'; ?>